mapper.select:
select 
from t_r_project
where workspace_id = #{workspaceId}
  and code = #{code}
limit 1

select p.id, p.code, p.workspace_id, p.name, p.description, p.params, p.created_by, p.created_at, p.updated_by, p.updated_at, u.username as created_by_username from t_r_project p left join t_r_user u on u.id = p.created_by where p.workspace_id = #{workspaceId}
and (p.name like concat('%', #{searchVal}, '%') or p.description like concat('%', #{searchVal}, '%'))
and p.created_by = #{createdBy}
order by p.created_at desc

select count(*)
from t_r_project
where workspace_id = #{workspaceId}
  and name = #{name}

select count(*)
from t_r_project
where workspace_id = #{workspaceId}
  and name = #{name}
  and id != #{excludeId}
